              weatherCode: weatherData.weatherCode,
            })
            .from(weatherData)
            .where(
              and(
                inArray(weatherData.airportCode, airportCodes),
                gte(weatherData.timestamp, weatherStartDate),
                lte(weatherData.timestamp, weatherEndDate),
              ),
            )
            .orderBy(weatherData.timestamp)
        : Promise.resolve([]),
