export type AirportInfo = {
  iataCode: string;
  icaoCode: string | null;
  name: string;
  city: string | null;
  latitude: number | null;
  longitude: number | null;
};

const airportsStore = writable<Record<string, AirportInfo>>({});

export function initAirports(data: Record<string, AirportInfo>) {
  airportsStore.set(data);
}

export function airportName(iata: string): string {
  let name = iata;
  const unsub = airportsStore.subscribe(a => {
    const airport = a[iata];
    name = airport?.name ?? iata;
  });
  unsub();
  return name;
}

export function getAirportCoords(iata: string): [number, number] | null {
  let coords: [number, number] | null = null;
  const unsub = airportsStore.subscribe(a => {
    const airport = a[iata];
    if (airport?.latitude != null && airport?.longitude != null) {
      coords = [airport.latitude, airport.longitude];
    }
  });
  unsub();
  return coords;
}

export function getAirportsForNearestSearch(): Array<{ iata: string; lat: number; lon: number }> {
  const result: Array<{ iata: string; lat: number; lon: number }> = [];
  const unsub = airportsStore.subscribe(a => {
    for (const [iata, info] of Object.entries(a)) {
      if (info.latitude != null && info.longitude != null) {
        result.push({ iata, lat: info.latitude, lon: info.longitude });
      }
    }
  });
  unsub();
  return result;
}

/**
 * Derives a short, badge-friendly label from a verbose flight status string.
 * Returns only the primary state word — no secondary detail (ETD times,
 * destination codes, gate numbers). That detail is surfaced separately on
 * the flight detail page via statusHasDetail / the full status callout.
 */export type FlightLike = {
  status?: string | null;
  canceled?: boolean | null;
  actualArrival?: string | Date | null;
  actualDeparture?: string | Date | null;
  scheduledArrival: string | Date;
  scheduledDeparture: string | Date;
};

export function isFlightCompleted(f: FlightLike): boolean {
  if (f.canceled === true) {
    return Date.now() > new Date(f.scheduledDeparture).getTime() + 60 * 60_000;
  }
  const s = f.status?.toLowerCase() ?? '';
  if (s.includes('landed') || s.includes('completed') || s.includes('diverted')) return true;
  if (f.actualArrival) return true;
  if (
    !f.actualDeparture &&
    (s.includes('delayed') || s.includes('etd') || s.includes('next info') ||
      s.includes('indefini') || s.includes('check in') || s.includes('check-in') ||
      s.includes('boarding') || s.includes('go to') || s.includes('approx'))
  ) return false;
  if (new Date(f.scheduledArrival).getTime() < Date.now() - 45 * 60_000) return true;
  return false;
}

export type DelayReason =
  | { reason: 'weather'; label: string; nextInfo: string | null }
  | { reason: 'indefinite'; label: string }
  | { reason: 'holding'; label: string }
  | { reason: 'check_in_suspended'; label: string };

export function extractDelayReason(status: string | null | undefined): DelayReason | null {
  if (!status) return null;
  const s = status.toLowerCase();
  if (!s.includes('delay') && !s.includes('indefini') && !s.includes('holding') && !s.includes('check in suspend') && !s.includes('check-in suspend')) return null;
  if (s.includes('weather') || (s.includes('due') && s.includes('weather')) || s.match(/due\s+weather/)) {
    const nextInfoMatch = status.match(/next\s+info(?:\s+at)?\s+([0-9]{1,2}:[0-9]{2})/i);
    return { reason: 'weather', label: 'Delayed due to weather', nextInfo: nextInfoMatch ? nextInfoMatch[1] : null };
  }
  if (s.includes('indefini')) {
    if (s.includes('weather')) {
      return { reason: 'weather', label: 'Indefinitely delayed due to weather', nextInfo: null };
    }
    return { reason: 'indefinite', label: 'Indefinitely delayed' };
  }
  if (s.includes('holding')) {
    return { reason: 'holding', label: 'Aircraft holding overhead' };
  }
  if (s.includes('check in suspend') || s.includes('check-in suspend')) {
    return { reason: 'check_in_suspended', label: 'Check-in suspended' };
  }
  return null;
}

export function shortenStatus(status: string | null | undefined): string {
  if (!status) return 'Scheduled';

  const s = status.toLowerCase();

  // Diverted must be checked before delayed — some strings contain both
  if (s.includes('diverted')) return 'Diverted';
  if (s.includes('diverting')) return 'Diverting';

  if (s.includes('delayed') || s.includes('new etd')) return 'Delayed';

  // "Approx HH:MM" — already a recognised short form used in the existing
  // yellow-tone handling; keep as-is (it's ≤ 12 chars)
  if (s.startsWith('approx')) {
    const t = status.match(/([0-9]{1,2}:[0-9]{2}(?:\s*[AP]M)?)/i);
    return t ? `Approx ${t[1]}` : 'Approx';
  }

  // Check-in messages — may also signal a delay or gate direction
  if (s.includes('check in') || s.includes('check-in')) {
    if (s.includes('delayed') || s.includes('etd')) return 'Delayed';
    return 'Check-In Open';
  }

  // Go to gate / departures → Boarding
  if (s.includes('go to')) return 'Boarding';

  // "Estimated dep. 4:45 PM" / "Estimated 12:54 PM"
  if (s.includes('estimated')) return 'Estimated';

  // PAX transfer messages
  if (s.includes('pax') || s.includes('passengers')) return 'Pax Transfer';

  // Holding overhead
  if (s.includes('holding')) return 'Holding';

  return status;
}

/**
 * Returns true when the full status string carries more detail than the
 * shortened badge label — used to decide whether to show the full text
 * as a secondary element on the detail page.
 */
export function statusHasDetail(status: string | null | undefined): boolean {
  if (!status) return false;
  return shortenStatus(status) !== status;
}

import type { RequestHandler } from './$types';
import { getDb } from '$lib/server/db';
import { debugResponse, debugError, validateSqlQuery } from '$lib/server/debug-helpers';
import { sql } from 'drizzle-orm';

/**
 * POST /api/debug/sql
 * Body: { "sql": "SELECT * FROM flights LIMIT 10" }
 *
 * Only SELECT, EXPLAIN, SHOW, DESCRIBE, and WITH (CTE) are allowed.
 * All other statements are rejected with 403.
 * Queries have a 30-second timeout via statement_timeout.
 */
export const POST: RequestHandler = async ({ request }) => {
  const t0 = performance.now();
  try {
    const body = await request.json() as { sql?: string };
    const query = body.sql?.trim();

    if (!query) return debugError('Missing "sql" field in request body', 400);

    // Validate query (SELECT-only, no dangerous keywords)
    const validation = validateSqlQuery(query);
    if (!validation.valid) {
      return debugError(validation.error, 403);
    }

    // Get the underlying pg pool for raw SQL execution
    const d = getDb();

    // Set session-level timeout for this query only, then reset
    await d.execute(sql`SET SESSION statement_timeout = '30s'`);

    let result;
    try {
      result = await d.execute(sql`${sql.raw(query)}`);
    } finally {
      await d.execute(sql`RESET statement_timeout`);
    }

    const queryMs = performance.now() - t0;

    // Log query for audit
    const truncated = query.length > 200 ? query.substring(0, 200) + '...' : query;
    console.log(`[debug/sql] ${queryMs}ms | rows=${result.rows.length} | ${truncated}`);

    return debugResponse(result.rows, queryMs);
  } catch (err) {
    const queryMs = performance.now() - t0;
    const message = err instanceof Error ? err.message : 'Query failed';
    console.error(`[debug/sql] ERROR ${queryMs}ms | ${message}`);
    return debugError(message, 500);
  }
};

import { json, error } from '@sveltejs/kit';
import type { RequestHandler } from './$types';
import { getDb } from '$lib/server/db';
import { pushSubscriptions } from '$lib/server/db';
import { eq, and } from 'drizzle-orm';

export const POST: RequestHandler = async ({ request }) => {
  let body: { subscription: PushSubscription; flightId: number; flightCode: string; flightDate: string };
  try {
    body = await request.json();
  } catch {
    throw error(400, 'Invalid JSON');
  }

  const { subscription, flightId, flightCode, flightDate } = body;
  if (!subscription?.endpoint || !flightId || !flightCode || !flightDate) {
    throw error(400, 'Missing required fields');
  }

  const db = getDb();
  await db
    .insert(pushSubscriptions)
    .values({
      endpoint: subscription.endpoint,
      subscription: subscription as unknown as Record<string, unknown>,
      flightId,
      flightCode,
      flightDate,
    })
    .onConflictDoUpdate({
      target: [pushSubscriptions.endpoint, pushSubscriptions.flightId],
      set: {
        subscription: subscription as unknown as Record<string, unknown>,
        flightCode,
        flightDate,
      },
    });

  return json({ ok: true });
};

export const DELETE: RequestHandler = async ({ request }) => {
  let body: { endpoint: string; flightId: number };
  try {
    body = await request.json();
  } catch {
    throw error(400, 'Invalid JSON');
  }

  const { endpoint, flightId } = body;
  if (!endpoint || !flightId) {
    throw error(400, 'Missing required fields');
  }

  const db = getDb();
  await db
    .delete(pushSubscriptions)
    .where(and(eq(pushSubscriptions.endpoint, endpoint), eq(pushSubscriptions.flightId, flightId)));

  return json({ ok: true });
};

import type { PageServerLoad } from './$types';
import { db, flights, flightStatusHistory, weatherData, aircraftPositions, flightTimes, airportDaylight } from '$lib/server/db';
import { eq, desc, and, lte, gte, inArray, isNotNull, asc } from 'drizzle-orm';
import { error } from '@sveltejs/kit';

export const load: PageServerLoad = async ({ params }) => {
  const id = parseInt(params.id, 10);
  if (isNaN(id)) throw error(404, 'Flight not found');

  try {
    const [flight] = await db.select().from(flights).where(eq(flights.id, id)).limit(1);
    if (!flight) throw error(404, 'Flight not found');

    const flightTime = flight.scheduledDeparture;
    const windowStart = new Date(flightTime.getTime() - 90 * 60000);
    const windowEnd   = new Date(Math.max(flightTime.getTime() + 90 * 60000, Date.now()));
    const airports    = [...new Set([flight.departureAirport, flight.arrivalAirport])];

    // Aircraft rotation: all flights for this registration within the last 24 hours
    // Shows the aircraft's journey throughout the day
    const rotationStart = new Date(flight.scheduledDeparture.getTime() - 24 * 60 * 60 * 1000);
    const rotationFlights = flight.aircraftRegistration
      ? await db.select({
          id: flights.id,
          flightNumber: flights.flightNumber,
          departureAirport: flights.departureAirport,
          arrivalAirport: flights.arrivalAirport,
          scheduledDeparture: flights.scheduledDeparture,
          scheduledArrival: flights.scheduledArrival,
          actualDeparture: flights.actualDeparture,
          actualArrival: flights.actualArrival,
          status: flights.status,
          canceled: flights.canceled,
          delayMinutes: flights.delayMinutes,
        })
        .from(flights)
        .where(and(
          eq(flights.aircraftRegistration, flight.aircraftRegistration),
          gte(flights.scheduledDeparture, rotationStart),
          isNotNull(flights.aircraftRegistration),
        ))
        .orderBy(asc(flights.scheduledDeparture))
      : [];

    // Get flight dates for daylight lookup
    const depDate = flight.scheduledDeparture.toISOString().split('T')[0];
    const arrDate = flight.scheduledArrival.toISOString().split('T')[0];

    const [rawStatusHistory, weatherRows, positionRows, times, daylightRows] = await Promise.all([
      db.select().from(flightStatusHistory)
        .where(eq(flightStatusHistory.flightId, id))
        .orderBy(desc(flightStatusHistory.statusTimestamp)),
      // Weather for both dep+arr airports near departure time
      db.select().from(weatherData)
        .where(and(
          inArray(weatherData.airportCode, airports),
          gte(weatherData.timestamp, windowStart),
          lte(weatherData.timestamp, windowEnd),
        ))
        .orderBy(desc(weatherData.timestamp)),
      // Latest position for this flight
      db.select().from(aircraftPositions)
        .where(eq(aircraftPositions.flightId, id))
        .orderBy(desc(aircraftPositions.positionTimestamp))
        .limit(1),
      // Estimated/actual times from API
      db.select().from(flightTimes)
        .where(eq(flightTimes.flightId, id)),
      // Daylight data for both airports
      db.select().from(airportDaylight)
        .where(and(
          inArray(airportDaylight.airportCode, airports),
          inArray(airportDaylight.date, [depDate, arrDate]),
        )),
    ]);

    // Most recent row per airport within the window
    const weatherMap: Record<string, typeof weatherData.$inferSelect> = {};
    const now = new Date();
    for (const row of weatherRows) {
      const existing = weatherMap[row.airportCode];
      const rowTs = new Date(row.timestamp).getTime();
      const nowMs = now.getTime();
      if (!existing) {
        weatherMap[row.airportCode] = row;
        continue;
      }
      const existingTs = new Date(existing.timestamp).getTime();
      const rowIsPast = rowTs <= nowMs;
      const existingIsPast = existingTs <= nowMs;
      if (rowIsPast && !existingIsPast) {
        weatherMap[row.airportCode] = row;
      } else if (rowIsPast && existingIsPast && rowTs > existingTs) {
        weatherMap[row.airportCode] = row;
      }
    }

    // Group daylight data by airport
    const daylightMap: Record<string, typeof airportDaylight.$inferSelect[]> = {};
    for (const row of daylightRows) {
      if (!daylightMap[row.airportCode]) daylightMap[row.airportCode] = [];
      daylightMap[row.airportCode].push(row);
    }

    // Collapse consecutive identical status messages — FR24 polls every ~6 minutes
    // and records a new row each time even when the estimated time hasn't changed,
    // producing long runs of identical entries. Keep only the first occurrence of
    // each message within a consecutive run (the oldest, since list is desc).
    // The list is newest-first so we walk it and drop entries whose message matches
    // the one immediately following them (i.e. the previous chronological entry).
    const seenBySource = new Map<string, Set<string>>();
    const latestGuernseyTs = rawStatusHistory
      .find(e => e.source === 'guernsey_airport')
      ?.statusTimestamp ?? null;
    const statusHistory = rawStatusHistory.filter((entry) => {
      const key = entry.source;
      if (!seenBySource.has(key)) seenBySource.set(key, new Set());
      const seen = seenBySource.get(key)!;
      if (seen.has(entry.statusMessage)) return false;
      seen.add(entry.statusMessage);
      if (
        entry.source === 'fr24' &&
        entry.statusMessage.toLowerCase().startsWith('estimated dep') &&
        latestGuernseyTs !== null &&
        new Date(latestGuernseyTs) >= new Date(entry.statusTimestamp)
      ) return false;
      return true;
    });

    return {
      flight,
      statusHistory,
      weatherMap,
      daylightMap,
      position: positionRows[0] ?? null,
      rotationFlights,
      times,
    };
  } catch (err: unknown) {
    if (typeof err === 'object' && err !== null && 'status' in err && (err as { status: number }).status === 404) throw err;
    console.error('Error loading flight:', err);
    throw error(500, 'Failed to load flight details');
  }
};

import { env } from '$env/dynamic/public';
import { fail } from '@sveltejs/kit';
import type { Actions, PageServerLoad } from './$types';

export const load: PageServerLoad = async () => {
  return {
    formspreeUrl: env.PUBLIC_FORMSPREE_URL || null,
  };
};

export const actions: Actions = {
  default: async ({ request }) => {
    const formspreeUrl = env.PUBLIC_FORMSPREE_URL;
    if (!formspreeUrl) {
      return fail(500, { error: 'Contact form is not configured.' });
    }

    const data = await request.formData();
    const name = data.get('name')?.toString().trim();
    const email = data.get('email')?.toString().trim();
    const type = data.get('type')?.toString();
    const message = data.get('message')?.toString().trim();

    if (!name || !email || !type || !message) {
      return fail(400, { error: 'All fields are required.' });
    }

    const validTypes = ['general', 'feature', 'bug'];
    if (!validTypes.includes(type)) {
      return fail(400, { error: 'Invalid enquiry type.' });
    }

    const res = await fetch(formspreeUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({ name, email, _replyto: email, type, message }),
    });

    if (!res.ok) {
      return fail(500, { error: 'Failed to send message. Please try again.' });
    }

    return { success: true };
  },
};

